<script setup>
const route = useRoute();
const { me, load } = useMe();
onMounted(() => load());
const ownsProfile = computed(() => Boolean(me.value.user && me.value.user.id === String(route.params.id)));
const id = computed(() => String(route.params.id || ""));
const { data: player, error, pending, refresh } = await useAsyncData("player-" + id.value, () => apiGet(`/api/player/${encodeURIComponent(id.value)}`));

if (import.meta.server && Number(error.value?.statusCode || error.value?.data?.statusCode) === 404) setResponseStatus(useRequestEvent(), 404);
const tracks = computed(() => player.value ? [{ title: "Ranked", key: "ranked", t: player.value.ranked }, { title: "Scrims", key: "scrim", t: player.value.scrim }] : []);
function runtime(sec) { const h = Math.floor((sec || 0) / 3600); const m = Math.round((sec || 0) % 3600 / 60); return h ? `${h}h ${m}m` : `${m}m`; }
useSeo(() => ({ title: player.value ? player.value.name : "Player", description: "Rank, Elo, win rate and recent rounds on the Ranked World ladder." }));
</script>
<template>
<main id="main" class="wrap section"><NuxtLink class="world-back" to="/leaderboard"><AppIcon name="arrowLeft" />Leaderboard</NuxtLink><div v-if="pending" class="world-skeleton" aria-label="Loading player" aria-busy="true" /><div v-else-if="error || !player" class="world-empty"><h1>{{ error?.statusCode === 404 || !error ? 'Player not found' : 'Could not load this player' }}</h1><p class="meta">{{ error?.statusCode === 404 || !error ? 'Check the player ID or find them on the leaderboard.' : 'Try loading the profile again.' }}</p><button v-if="error && error.statusCode !== 404" class="btn" @click="refresh">Try again</button><NuxtLink v-else class="btn" to="/leaderboard">Find a player</NuxtLink></div><template v-else><header class="world-profile-heading"><PlayerAvatar :name="player.discord?.name || player.name" :src="player.discord?.avatar || player.avatar || ''" :discord-id="player.discordId || ''" :size="68" /><div><h1>{{ player.discord?.name || player.name }}</h1><p class="meta">{{ player.name }}</p></div><span v-if="player.position" class="world-profile-standing"><strong>#{{ num(player.position) }}</strong>on the ranked ladder</span></header><div class="world-profile-status"><span v-if="player.banned" class="chip bad">Rank banned</span><span v-if="!player.linked" class="chip">Account disconnected</span><span v-if="player.inCode" class="chip chip--live">Playing in {{ player.inCode.code || 'a code' }}</span></div><ProgressIdentity :player="player" /><ProfileCardStudio v-if="ownsProfile" :position="player.position" /><section v-else-if="player.playerCard" class="world-profile-card"><h2>Player card</h2><ProfileCard :profile="player.playerCard.profile" :card="player.playerCard.card" /></section><div class="world-profile-tracks"><section v-for="card in tracks" :key="card.key"><div class="world-section-head"><h2>{{ card.title }} record</h2><span class="meta">{{ card.t.tier.name }} / {{ card.t.tier.category }}</span></div><dl class="world-stat-grid"><div><dt>Elo</dt><dd>{{ num(card.t.elo) }}</dd></div><div><dt>Peak Elo</dt><dd>{{ num(card.t.peakElo) }}</dd></div><div><dt>Wins</dt><dd>{{ num(card.t.wins) }}</dd></div><div><dt>Rounds</dt><dd>{{ num(card.t.rounds) }}</dd></div><div><dt>Win rate</dt><dd>{{ card.t.winRate }}%</dd></div><div><dt>Time played</dt><dd>{{ runtime(card.t.survivalSeconds) }}</dd></div><div><dt>Tags</dt><dd>{{ num(card.t.tags) }}</dd></div></dl><p class="meta">{{ card.t.tier.isTop ? 'Top division reached' : card.t.tier.eloToNext + ' Elo to the next division' }}</p></section></div><section class="world-profile-results"><div class="world-section-head"><h2>Recent matches</h2><span class="meta">{{ player.matches.length }} recorded rounds</span></div><div v-if="player.matches.length" class="world-table-scroll" tabindex="0" role="region" aria-label="Recent match results"><table class="world-table"><thead><tr><th>Code</th><th>Result</th><th>Elo change</th><th>Rating</th><th>Place</th><th>Tags</th><th>Played</th></tr></thead><tbody><tr v-for="(m,i) in player.matches" :key="i"><td class="mono">{{ m.code || 'Private room' }}<small>{{ m.track === 'scrim' ? 'Scrims' : 'Ranked' }}</small></td><td>{{ m.won ? 'Win' : 'Loss' }}</td><td :class="m.delta >= 0 ? 'pos' : 'neg'">{{ m.delta > 0 ? '+' : '' }}{{ m.delta ?? 0 }}</td><td>{{ m.afterElo ?? 'Unknown' }}</td><td>{{ m.placement == null ? 'N/A' : m.placement + 1 }} / {{ m.lobbySize ?? 'Unknown' }}</td><td>{{ num(m.tags) }}</td><td :title="exact(m.at)">{{ ago(m.at) }}</td></tr></tbody></table></div><div v-else class="world-empty"><h3>No matches yet</h3><p class="meta">Scored rounds will appear after this player competes.</p><NuxtLink class="btn" to="/play">Find a game</NuxtLink></div></section></template></main>
</template>

<style scoped>.world-profile-card{margin:32px 0;padding:28px 0;border-top:1px solid #ffffff16}.world-profile-card h2{margin-bottom:24px}.world-profile-card .player-card{max-width:980px;margin:auto}</style>
